import Sidebar from "../../components/ui/sidebar/sidebar.marko";
import SidebarHeader from "../../components/ui/sidebar/header.marko";
import SidebarContent from "../../components/ui/sidebar/content.marko";
import SidebarFooter from "../../components/ui/sidebar/footer.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import NavMain, { type NavMainItem } from "./nav-main.marko";
import NavProjects, { type ProjectItem } from "./nav-projects.marko";
import NavSecondary, { type NavSecondaryItem } from "./nav-secondary.marko";
import NavUser, { type NavUser as NavUserData } from "./nav-user.marko";

export interface Input {
  open?: boolean;
}

// NOTE: shadcn's SidebarRail (a hover/drag handle on the sidebar's right
// edge for resizing/toggling) has no equivalent in our sidebar sub-parts
// yet, so it is omitted here, following the precedent set in
// blocks/sidebar-05/app-sidebar.marko. SidebarTrigger in the page header
// covers open/close.

// This is sample data.
static const USER: NavUserData = {
  name: "shadcn",
  email: "m@example.com",
  avatar: "",
};

static const NAV_MAIN: NavMainItem[] = [
  {
    id: "playground",
    title: "Playground",
    url: "#",
    icon: "square-terminal",
    isActive: true,
    items: [
      { id: "history", title: "History", url: "#" },
      { id: "starred", title: "Starred", url: "#" },
      { id: "settings", title: "Settings", url: "#" },
    ],
  },
  {
    id: "models",
    title: "Models",
    url: "#",
    icon: "bot",
    items: [
      { id: "genesis", title: "Genesis", url: "#" },
      { id: "explorer", title: "Explorer", url: "#" },
      { id: "quantum", title: "Quantum", url: "#" },
    ],
  },
  {
    id: "documentation",
    title: "Documentation",
    url: "#",
    icon: "book-open",
    items: [
      { id: "introduction", title: "Introduction", url: "#" },
      { id: "get-started", title: "Get Started", url: "#" },
      { id: "tutorials", title: "Tutorials", url: "#" },
      { id: "changelog", title: "Changelog", url: "#" },
    ],
  },
  {
    id: "settings",
    title: "Settings",
    url: "#",
    icon: "settings",
    items: [
      { id: "general", title: "General", url: "#" },
      { id: "team", title: "Team", url: "#" },
      { id: "billing", title: "Billing", url: "#" },
      { id: "limits", title: "Limits", url: "#" },
    ],
  },
];

static const NAV_SECONDARY: NavSecondaryItem[] = [
  { id: "support", title: "Support", url: "#", icon: "life-buoy" },
  { id: "feedback", title: "Feedback", url: "#", icon: "send" },
];

static const PROJECTS: ProjectItem[] = [
  { id: "design-engineering", name: "Design Engineering", url: "#", icon: "frame" },
  { id: "sales-marketing", name: "Sales & Marketing", url: "#", icon: "pie-chart" },
  { id: "travel", name: "Travel", url: "#", icon: "map" },
];

<Sidebar open=input.open>
  <@content>
    <SidebarHeader>
      <SidebarMenu>
        <SidebarMenuItem>
          <SidebarMenuButton href="#" class="h-12">
            <div
              class="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
                class="size-4"
              >
                <rect width="18" height="18" x="3" y="3" rx="2"/>
                <path d="M7 7h.01"/>
                <path d="M11 7h6"/>
                <path d="M7 11h.01"/>
                <path d="M11 11h6"/>
                <path d="M7 15h.01"/>
                <path d="M11 15h6"/>
              </svg>
            </div>
            <div class="grid flex-1 text-left text-sm leading-tight">
              <span class="truncate font-medium">Acme Inc</span>
              <span class="truncate text-xs">Enterprise</span>
            </div>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </SidebarMenu>
    </SidebarHeader>
    <SidebarContent>
      <NavMain items=NAV_MAIN/>
      <NavProjects projects=PROJECTS class="group-data-[collapsible=icon]:hidden"/>
      <NavSecondary items=NAV_SECONDARY class="mt-auto"/>
    </SidebarContent>
    <SidebarFooter>
      <NavUser user=USER/>
    </SidebarFooter>
  </@content>
</Sidebar>

import SidebarGroup from "../../components/ui/sidebar/group.marko";
import SidebarGroupLabel from "../../components/ui/sidebar/group-label.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import Collapsible from "../../components/ui/collapsible/collapsible.marko";
import NavIcon, { type NavIconName } from "./nav-icon.marko";

export interface NavMainLeafItem {
  id: string;
  title: string;
  url: string;
}

export interface NavMainItem {
  id: string;
  title: string;
  url: string;
  icon: NavIconName;
  isActive?: boolean;
  items?: NavMainLeafItem[];
}

export interface Input {
  items: NavMainItem[];
}

// NOTE: our sidebar sub-parts have no SidebarMenuAction / SidebarMenuSub /
// SidebarMenuSubButton equivalents yet, so the collapsible chevron action
// and the indented sub-menu list are composed here from Collapsible +
// plain markup, following the pattern already established in
// blocks/sidebar-05/app-sidebar.marko. Deviation from the source, noted
// per block-porting rules.
//
// Our SidebarMenuButton also has no `tooltip` prop (the source's
// icon-only-collapsed hover tooltip), so it is omitted here.

<SidebarGroup>
  <SidebarGroupLabel>Platform</SidebarGroupLabel>
  <SidebarMenu>
    <for|item| of=input.items by=(item) => item.id>
      <const/hasSubItems=(item.items ?? []).length !== 0/>
      <let/isOpen=!!item.isActive/>
      <if=hasSubItems>
        <Collapsible
          open=isOpen
          openChange(open) {
            isOpen = open;
          }
          class="group/collapsible"
        >
          <@trigger|attrs|>
            <SidebarMenuItem>
              <SidebarMenuButton href=item.url>
                <NavIcon name=item.icon/>
                <span>${item.title}</span>
              </SidebarMenuButton>
              <button
                ...attrs
                type="button"
                data-slot="sidebar-menu-action"
                class="absolute top-1.5 right-1 flex aspect-square w-5 items-center justify-center rounded-md p-0 text-sidebar-foreground outline-none ring-sidebar-ring transition-transform hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 peer-hover/menu-button:text-sidebar-accent-foreground group-data-[state=open]/collapsible:rotate-90"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  stroke-width="2"
                  stroke-linecap="round"
                  stroke-linejoin="round"
                  class="size-4"
                >
                  <path d="m9 18 6-6-6-6"/>
                </svg>
                <span class="sr-only">Toggle</span>
              </button>
            </SidebarMenuItem>
          </@trigger>
          <@content>
            <ul
              class="mx-3.5 flex min-w-0 translate-x-px flex-col gap-1 border-l border-sidebar-border px-2.5 py-0.5"
            >
              <for|leaf| of=item.items by=(leaf) => leaf.id>
                <li class="group/menu-sub-item relative">
                  <a
                    href=leaf.url
                    class="flex h-7 min-w-0 -translate-x-px items-center gap-2 overflow-hidden rounded-md px-2 text-sm text-sidebar-foreground outline-none ring-sidebar-ring hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground"
                  >
                    <span>${leaf.title}</span>
                  </a>
                </li>
              </for>
            </ul>
          </@content>
        </Collapsible>
      </if>
      <else>
        <SidebarMenuItem>
          <SidebarMenuButton href=item.url>
            <NavIcon name=item.icon/>
            <span>${item.title}</span>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </else>
    </for>
  </SidebarMenu>
</SidebarGroup>

import SidebarGroup from "../../components/ui/sidebar/group.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import NavIcon, { type NavIconName } from "./nav-icon.marko";

export interface NavSecondaryItem {
  id: string;
  title: string;
  url: string;
  icon: NavIconName;
}

export interface Input {
  items: NavSecondaryItem[];
  class?: string;
}

<SidebarGroup class=input.class>
  <SidebarMenu>
    <for|item| of=input.items by=(item) => item.id>
      <SidebarMenuItem>
        <SidebarMenuButton href=item.url class="text-sm">
          <NavIcon name=item.icon/>
          <span>${item.title}</span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </for>
  </SidebarMenu>
</SidebarGroup>

import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import Avatar from "../../components/ui/avatar/avatar.marko";
import DropdownMenu from "../../components/ui/dropdown-menu/dropdown-menu.marko";

export interface NavUser {
  name: string;
  email: string;
  avatar: string;
}

export interface Input {
  user: NavUser;
}

// The dropdown-menu `<@item>` attr tag accepts a markup `content` body plus
// a `class` override on label entries (see
// ui/dropdown-menu/dropdown-menu.marko), so the source's rich
// DropdownMenuLabel — avatar + name/email, with `p-0 font-normal` replacing
// the default padded/muted label classes — ports faithfully instead of
// being flattened to a plain string label.
//
// Width: the source sizes DropdownMenuContent with
// `w-(--radix-dropdown-menu-trigger-width)`, a Radix CSS var mirroring the
// trigger's measured width. zag's popper exposes the same measurement as
// `--reference-width` on the positioner (see @zag-js/popper
// get-placement.js/get-styles.js), so `w-(--reference-width)` is the
// visual-equivalent mapping for our primitive.

<SidebarMenu>
  <SidebarMenuItem>
    <DropdownMenu class="w-(--reference-width) min-w-56 rounded-lg">
      <@trigger|attrs|>
        <SidebarMenuButton
          ...attrs
          class="h-12 data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground md:h-8 md:p-0"
        >
          <Avatar src=input.user.avatar alt=input.user.name fallback="CN" class="size-8 rounded-lg"/>
          <div class="grid flex-1 text-left text-sm leading-tight">
            <span class="truncate font-medium">${input.user.name}</span>
            <span class="truncate text-xs">${input.user.email}</span>
          </div>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class="ml-auto size-4"
          >
            <path d="m7 15 5 5 5-5"/>
            <path d="m7 9 5-5 5 5"/>
          </svg>
        </SidebarMenuButton>
      </@trigger>
      <@item type="label" class="p-0 font-normal">
        <div class="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
          <Avatar src=input.user.avatar alt=input.user.name fallback="CN" class="size-8 rounded-lg"/>
          <div class="grid flex-1 text-left text-sm leading-tight">
            <span class="truncate font-medium">${input.user.name}</span>
            <span class="truncate text-xs">${input.user.email}</span>
          </div>
        </div>
      </@item>
      <@item type="separator"/>
      <@item type="item" value="upgrade" label="Upgrade to Pro"/>
      <@item type="separator"/>
      <@item type="item" value="account" label="Account"/>
      <@item type="item" value="billing" label="Billing"/>
      <@item type="item" value="notifications" label="Notifications"/>
      <@item type="separator"/>
      <@item type="item" value="logout" label="Log out"/>
    </DropdownMenu>
  </SidebarMenuItem>
</SidebarMenu>

import SidebarProvider from "../../components/ui/sidebar/provider.marko";
import SidebarTrigger from "../../components/ui/sidebar/trigger.marko";
import Separator from "../../components/ui/separator/separator.marko";
import Breadcrumb from "../../components/ui/breadcrumb/breadcrumb.marko";
import BreadcrumbItem from "../../components/ui/breadcrumb/item.marko";
import BreadcrumbLink from "../../components/ui/breadcrumb/link.marko";
import BreadcrumbPage from "../../components/ui/breadcrumb/page.marko";
import BreadcrumbSeparator from "../../components/ui/breadcrumb/separator.marko";
import AppSidebar from "./app-sidebar.marko";

// NOTE: the source renders inside a shadcn `SidebarInset` (Sidebar
// variant="inset"), which floats the content area as a rounded, shadowed
// panel offset from the sidebar. Our Sidebar has no `variant` prop, so the
// inset look is composed directly on the content wrapper below instead.
// Deviation from the source, noted per block-porting rules.

<SidebarProvider width="16rem">
  <@sidebar|{ open }|>
    <AppSidebar open=open/>
  </@sidebar>
  <@content|{ open, toggle }|>
    <div class="relative flex min-w-0 flex-1 flex-col bg-background md:m-2 md:ml-0 md:rounded-xl md:shadow-sm md:peer-data-[state=collapsed]:ml-2">
      <header class="flex h-16 shrink-0 items-center gap-2">
        <div class="flex items-center gap-2 px-4">
          <SidebarTrigger open=open toggle=toggle class="-ml-1"/>
          <Separator orientation="vertical" class="mr-2 h-4"/>
          <Breadcrumb>
            <BreadcrumbItem class="hidden md:block">
              <BreadcrumbLink href="#">Build Your Application</BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator class="hidden md:block"/>
            <BreadcrumbItem>
              <BreadcrumbPage>Data Fetching</BreadcrumbPage>
            </BreadcrumbItem>
          </Breadcrumb>
        </div>
      </header>
      <div class="flex flex-1 flex-col gap-4 p-4 pt-0">
        <div class="grid auto-rows-min gap-4 md:grid-cols-3">
          <div class="aspect-video rounded-xl bg-muted/50"></div>
          <div class="aspect-video rounded-xl bg-muted/50"></div>
          <div class="aspect-video rounded-xl bg-muted/50"></div>
        </div>
        <div class="min-h-[100vh] flex-1 rounded-xl bg-muted/50 md:min-h-min"></div>
      </div>
    </div>
  </@content>
</SidebarProvider>
